import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/Cart.css";

const Cart = () => {
  const navigate = useNavigate();
  const userId = sessionStorage.getItem("userId");
  const [cartItems, setCartItems] = useState([]);
  const [totals, setTotals] = useState({ subtotal: 0, tax: 0, shipping: 0, total: 0 });

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/cart/user/${userId}`)
      .then((res) => res.json())
      .then((items) => {
        setCartItems(items);
        calculateTotals(items);
      })
      .catch((err) => console.error("Error loading cart:", err));
  }, [userId]);

  const calculateTotals = (items) => {
    const subtotal = items.reduce((sum, item) => sum + parseFloat(item.price), 0);
    const tax = subtotal * 0.08;
    const shipping = Math.floor(Math.random() * 5) + 3;
    const total = subtotal + tax + shipping;
    setTotals({ subtotal, tax, shipping, total });
  };

  const handleCheckout = () => navigate("/checkout");

  return (
    <div className="cart-wrapper">
      <Navbar />
      <div className="cart-main">
        <h2>🛒 Your Cart</h2>
        {cartItems.length === 0 ? (
          <p>No items in cart.</p>
        ) : (
          <div className="cart-content">
            <ul>
              {cartItems.map((item) => (
                <li key={item.listing_id}>
                  <strong>{item.title}</strong> - ${item.price}
                </li>
              ))}
            </ul>
            <div className="summary-box">
              <p>Subtotal: ${totals.subtotal.toFixed(2)}</p>
              <p>Tax (8%): ${totals.tax.toFixed(2)}</p>
              <p>Shipping: ${totals.shipping}</p>
              <h3>Total: ${totals.total.toFixed(2)}</h3>
              <button className="checkout-btn" onClick={handleCheckout}>Proceed to Checkout</button>
            </div>
          </div>
        )}
      </div>
      <Footer />
    </div>
  );
};

export default Cart;
